func ltWord(wd *port.Cells, et *port.Cells, b []byte) int32 {
	// Append one word holding the UTF-8 text b; answers its row.
	var ts int32 = port.CellsLen(et)
	model.TextAppendUtf8(et, b, 0, port.BlobLen(b))
	var r int32 = evidence.WdNew(wd, 1, 7200, 1000, 9000, 2200, 7200, 1800, 9000, 1800, 0, 0, ts, port.CellsLen(et)-ts, -1, -1, -1)
	evidence.WdSet(wd, r, evidence.WfSize(), 1100)
	return r
}

func ltKw(wd *port.Cells, et *port.Cells, b []byte) int32 {
	// `nt-keyword` of a word spelled b.
	var w int32 = ltWord(wd, et, b)
	return notes.NtKeyword(wd, et, w)
}

func ltNb(wd *port.Cells, et *port.Cells, b []byte) int32 {
	// `nt-number-body` of a word spelled b.
	var w int32 = ltWord(wd, et, b)
	return notes.NtNumberBody(wd, et, w)
}

func ltParse(ws *port.Cells, b []byte) int32 {
	// `ls-parse` of a word spelled b: answers its class; the rest is in `ws`.
	var wd *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var w int32 = ltWord(wd, et, b)
	return lists.LsParse(wd, et, w, ws)
}

func ltWs(ws *port.Cells) int32 {
	port.CellsDrop(ws, 0)
	var i int32 = 0
	for i < 8 {
		port.CellsPush(ws, 0)
		i += 1
	}
	return 0
}

