func ltItem(nodes *port.Cells, attrs *port.Cells, text *port.Cells, parent int32, marker []byte, body []byte, scheme int32, value int32, x int32) int32 {
	// An `item` of the old Model under parent: its marker, text, scheme (`sub`), value (`aux`), text x (`fk-box`).
	var it int32 = model.NodeNew(nodes, model.NkItem(), parent)
	var t0 int32 = port.CellsLen(text)
	model.TextAppendUtf8(text, body, 0, port.BlobLen(body))
	model.NodeSetText(nodes, it, t0, port.CellsLen(text)-t0)
	var m0 int32 = port.CellsLen(text)
	model.TextAppendUtf8(text, marker, 0, port.BlobLen(marker))
	model.NodeSetAttrText(nodes, attrs, it, model.FkMarker(), m0, port.CellsLen(text)-m0)
	model.NodeSetSub(nodes, it, scheme)
	model.NodeSetAux(nodes, it, value)
	model.NodeSetAttrInt(nodes, attrs, it, model.FkBox(), x)
	return it
}

func ltRs(on *port.Cells, oa *port.Cells, orr *port.Cells, text *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells) int32 {
	// `rs-run` with its scratch made here; answers the new node count.
	var nm *port.Cells = port.NewCells()
	var stk *port.Cells = port.NewCells()
	var used *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var lay *port.Cells = port.NewCells()
	return restruct.RsRun(on, oa, orr, text, nodes, attrs, regions, nm, stk, used, out, lay)
}

func TestItemsBecomeListsNestedByTheXOfTheirText(emonT *testing.T) {
	var on *port.Cells = port.NewCells()
	var oa *port.Cells = port.NewCells()
	var orr *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	model.ModelInit(on, oa, orr, text, pages, ledger, layout)
	var sec int32 = model.NodeNew(on, model.NkSection(), 0)
	ltItem(on, oa, text, sec, port.TextBlob("1."), port.TextBlob("one"), lists.LsScDecimal(), 1, 9000)
	ltItem(on, oa, text, sec, port.TextBlob("2."), port.TextBlob("two"), lists.LsScDecimal(), 2, 9000)
	ltItem(on, oa, text, sec, port.TextBlob("a."), port.TextBlob("inner a"), lists.LsScLowerAlpha(), 1, 12000)
	ltItem(on, oa, text, sec, port.TextBlob("b."), port.TextBlob("inner b"), lists.LsScLowerAlpha(), 2, 12000)
	ltItem(on, oa, text, sec, port.TextBlob("3."), port.TextBlob("three"), lists.LsScDecimal(), 3, 9000)
	ltItem(on, oa, text, sec, port.TextBlob("5."), port.TextBlob("five"), lists.LsScDecimal(), 5, 9000)
	model.NodeNew(on, model.NkParagraph(), sec)
	ltItem(on, oa, text, sec, port.TextBlob("1."), port.TextBlob("again"), lists.LsScDecimal(), 1, 9000)
	port.AssertEq(emonT, ltRs(on, oa, orr, text, nodes, attrs, regions), 13, "seven items, two lists and a nested one, a paragraph")
	port.AssertEq(emonT, model.NodeKind(nodes, 0), 1, "the document")
	port.AssertEq(emonT, model.NodeKind(nodes, 2), model.NkList(), "the first item opens a list under the section")
	port.AssertEq(emonT, model.NodeParent(nodes, 2), 1, "in the section")
	port.AssertEq(emonT, model.NodeSub(nodes, 2), 2, "an ordered one")
	port.AssertEq(emonT, model.NodeKind(nodes, 3), model.NkItem(), "its first item")
	port.AssertEq(emonT, model.NodeKind(nodes, 5), model.NkList(), "the lettered items are a list of their own")
	port.AssertEq(emonT, model.NodeParent(nodes, 5), 4, "inside the item before them")
	port.AssertEq(emonT, model.NodeKind(nodes, 8), model.NkItem(), "then the third item continues the numbered list")
	port.AssertEq(emonT, model.NodeParent(nodes, 8), 2, "in the outer list")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 9, model.FkValue(), -1), 5, "the item that skips gets an explicit value")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 8, model.FkValue(), -1), -1, "and the one that does not, none")
	port.AssertEq(emonT, model.NodeKind(nodes, 10), model.NkParagraph(), "a paragraph ends the list")
	port.AssertEq(emonT, model.NodeKind(nodes, 11), model.NkList(), "and a numbering that starts again is a new list")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "the new Model is in document order")
}

